  const gesamt = (m, typ) => [...m.values()].filter((x) => x.typ === typ).reduce((s, x) => s + x.betrag, 0);
  const vergleich = [
    { label: "Rechnungen", neu: gesamt(a, "Rechnung"), alt: gesamt(b, "Rechnung") },
    { label: "Gutschriften", neu: gesamt(a, "Gutschrift"), alt: gesamt(b, "Gutschrift") },
