  for (const [k, z] of Object.entries(zr)) {
    const r = await versuch(() => energie.enPeriodenwerte(SYS(), g.id, z.von, z.bis));
    if (!r.ok) {
      fehlt = r;
      werte[k] = null;
      continue;
