          </div>
        </div>
        <div className="ov-hero-in absolute -bottom-6 left-2 hidden w-[52%] sm:block" style={{ "--ov-delay": "480ms" }}>
          <MockAbschluss />
        </div>
      </div>
    </div>
  );
}

